// =================== DECLARE_TIER_POSITION_STATIC_HASH_SET ===================

// Verifies that a newly declared hash set initializes its size property to
// exactly zero.
TEST(TierPositionStaticHashSetTest, InitializesSizeToZero) {
    DECLARE_TIER_POSITION_STATIC_HASH_SET(my_set, 16);
    EXPECT_EQ(my_set.size, 0)
        << "A freshly initialized set must contain exactly zero elements.";
}

// Verifies that every slot in the newly allocated key array is initialized to
// the empty sentinel value.
TEST(TierPositionStaticHashSetTest, InitializesAllSlotsToSentinel) {
    constexpr int kCapacity = 16;
    DECLARE_TIER_POSITION_STATIC_HASH_SET(my_set, kCapacity);

    for (int i = 0; i < kCapacity; ++i) {
        EXPECT_EQ(my_set.keys[i].tier, TIER_POSITION_STATIC_HASH_SET_EMPTY_TIER)
            << "Array index " << i
            << " was not initialized to the sentinel value.";
    }
}

// Verifies that the macro successfully compiles and sets the correct capacity
// mask for the minimum valid power of two (1).
TEST(TierPositionStaticHashSetTest, CompilesWithSmallestPowerOfTwo) {
    DECLARE_TIER_POSITION_STATIC_HASH_SET(my_set, 1);
    EXPECT_EQ(my_set.capacity_mask, 0)
        << "Capacity mask for capacity 1 must be exactly 0 (1 - 1).";
    EXPECT_EQ(my_set.size, 0) << "Size must be exactly 0.";
}

